{"command": "SESSION=~/.codex/sessions/2026/06/06/rollout-2026-06-06T16-28-36-019e9c0c-5d5c-70d3-bcc9-359b6184471f.jsonl; tail -200 "$SESSION" | python3 -c 'import sys,json
for line in sys.stdin:
    line=line.strip()
    if not line: continue
    o=json.loads(line); t=o.get("type"); p=o.get("payload",{})
    ts=o.get("timestamp","")[:19]
    if t=="response_item":
        pt=p.get("type")
        if pt=="message":
            c=p.get("content",[])
            if isinstance(c,list):
                for part in c:
                    if isinstance(part,dict) and part.get("type") in ("output_text","input_text"):
                        print(ts,"MSG",p.get("role"),part.get("text","")[:1000])
            elif isinstance(c,str):
                print(ts,"MSG",p.get("role"),c[:1000])
        elif pt in ("function_call","function_call_output"):
            name=p.get("name") or ""
            args=p.get("arguments","") if pt=="function_call" else p.get("output","")
            print(ts,pt.upper(),name,str(args)[:300])
    elif t=="event_msg" and p.get("type")=="agent_message":
        print(ts,"AGENT",str(p.get("message",""))[:1000])'"}

