import json, datetime
root='/Users/zxz/.kimi-code/sessions/wd_business-semantic-abstraction-refactor_be0055d16dc5/session_b0333bee-3198-4583-b54d-56495140acc7/agents/main/wire.jsonl'
def ts(ms):
    return datetime.datetime.fromtimestamp(ms/1000).strftime('%m-%d %H:%M:%S')
turns={}
for line in open(root):
    line=line.strip()
    if not line: continue
    o=json.loads(line); t=o.get('type'); tm=o.get('time')
    if t=='turn.prompt':
        text=' '.join(p.get('text','') for p in o.get('input',[]) if isinstance(p,dict) and p.get('type')=='text')
        turns[len(turns)]={'prompt':text,'time':tm}
    elif t=='turn.ended':
        # find matching by count? turnId maybe
        tid=o.get('turnId')
        for tr in turns.values():
            if tr.get('turnId') is None:
                tr['turnId']=tid; tr['ended']=o; break
for i,tr in turns.items():
    print(f"TURN {i} {ts(tr['time'])} -> {ts(tr.get('ended',{}).get('time',tr['time']))} reason={tr.get('ended',{}).get('reason')}")
    print('  PROMPT:', tr['prompt'][:800].replace('\n',' | '))
PY"}

