import json, datetime
path='/Users/zxz/.kimi-code/sessions/wd_business-semantic-abstraction-refactor_be0055d16dc5/session_b0333bee-3198-4583-b54d-56495140acc7/agents/agent-19/wire.jsonl'
def ts(ms):
    try: return datetime.datetime.fromtimestamp(ms/1000).strftime('%H:%M:%S')
    except: return ''
calls={}; results={}
for line in open(path):
    o=json.loads(line); t=o.get('type')
    if t=='context.append_loop_event':
        e=o.get('event',{}); cid=e.get('toolCallId')
        if e.get('type')=='tool.call':
            cmd=e.get('args',{}).get('command','')
            if 'pytest' in cmd or 'EOF' in cmd:
                calls[cid]=(o.get('time'),e.get('name'),cmd)
        elif e.get('type')=='tool.result':
            results[cid]=(o.get('time'),e.get('result',{}).get('output',''))
for cid,(tm,name,cmd) in sorted(calls.items(), key=lambda kv:kv[1][0]):
    print(f"\n=== CALL {ts(tm)} {name} {cid[-8:]} ===\n{cmd[:1500]}")
    rt,out=results.get(cid,(None,''))
    if out:
        print(f"--- RESULT {ts(rt) if rt else ''} len={len(out)} ---")
        print(out[:6000])
PY"}

