import json, datetime
for name in ['agent-17','agent-18']:
    path=f'/Users/zxz/.kimi-code/sessions/wd_business-semantic-abstraction-refactor_be0055d16dc5/session_b0333bee-3198-4583-b54d-56495140acc7/agents/{name}/wire.jsonl'
    def ts(ms):
        try: return datetime.datetime.fromtimestamp(ms/1000).strftime('%m-%d %H:%M:%S')
        except: return ''
    texts=[]; calls=[]; results=[]; events=[]
    for line in open(path):
        o=json.loads(line); t=o.get('type')
        if t=='context.append_loop_event':
            e=o.get('event',{}); et=e.get('type')
            if et=='content.part':
                p=e.get('part',{})
                if p.get('type')=='text': texts.append((o.get('time'),'TEXT',p.get('text','')))
            elif et=='tool.call':
                cmd=e.get('args',{}).get('command','')[:400]
                calls.append((o.get('time'),'CALL',e.get('name'),cmd))
            elif et=='tool.result':
                out=e.get('result',{}).get('output','')
                results.append((o.get('time'),'RESULT',str(out)[:600].replace('\n',' | ')))
        elif t in ('turn.ended','task.started','task.terminated'):
            events.append((o.get('time'),t.upper(),json.dumps(o,ensure_ascii=False)[:400]))
    print(f"\n========== {name} ==========")
    print('--- last 10 texts ---')
    for tm,k,tx in texts[-10:]: print(ts(tm),tx[:1800].replace('\n',' '))
    print('--- last 12 calls ---')
    for tm,k,n,cmd in calls[-12:]: print(ts(tm),k,n,cmd[:200])
    print('--- events ---')
    for tm,k,v in events[-6:]: print(ts(tm),k,v[:300])
PY"}

