def nocobase_mapping_runtime_eligible(
    mapping: dict[str, Any] | None,
) -> bool:
    if not isinstance(mapping, dict):
        return False
    if not mapping.get("enabled", True):
        return False
    metadata = mapping.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    if bool(mapping.get("stale")) or bool(metadata.get("stale")):
        return False
    runtime_eligible = mapping.get("runtime_eligible", metadata.get("runtime_eligible"))
    if runtime_eligible is False:
        return False
    if isinstance(runtime_eligible, str) and runtime_eligible.strip().casefold() in {"false", "0", "no", "disabled", "inactive"}:
        return False
    mapping_source = nocobase_mapping_source(mapping)
    if mapping_source not in _RUNTIME_FACT_MAPPING_SOURCES:
        return False
    if mapping_source == "published_ontology_mapping":
        try:
            published_connector_mapping_evidence(mapping)
        except ValueError:
            return False
    return True

def published_connector_mapping_evidence(mapping: Any) -> dict[str, str]:
    payload = _public_ontology_payload(mapping)
    metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
    mapping_source = str(metadata.get("mapping_source") or payload.get("mapping_source") or "").strip()
    ontology_mapping_id = str(metadata.get("ontology_mapping_id") or payload.get("ontology_mapping_id") or "").strip()
    if mapping_source != "published_ontology_mapping" or not ontology_mapping_id:
        raise ValueError("NOCOBASE_PUBLISHED_MAPPING_REQUIRED")
    semantic_snapshot_id = str(
        metadata.get("semantic_snapshot_id") or payload.get("semantic_snapshot_id") or ""
    ).strip()
    semantic_snapshot_hash = str(
        metadata.get("semantic_snapshot_hash") or payload.get("semantic_snapshot_hash") or ""
    ).strip()
    if (
        not semantic_snapshot_hash
        or semantic_snapshot_id != f"semantic-runtime:{semantic_snapshot_hash}"
    ):
        raise ValueError("NOCOBASE_SEMANTIC_RUNTIME_SNAPSHOT_REQUIRED")
    return {
        "mapping_source": mapping_source,
        "ontology_mapping_id": ontology_mapping_id,
        "semantic_snapshot_id": semantic_snapshot_id,
        "semantic_snapshot_hash": semantic_snapshot_hash,
    }


def _mapping_has_published_object_identity(mapping: dict[str, Any]) -> bool:
    metadata = mapping.get("metadata") if isinstance(mapping.get("metadata"), dict) else {}
    ontology = metadata.get("ontology") if isinstance(metadata.get("ontology"), dict) else {}
    collection_name = str(mapping.get("collection_name") or "").strip()
    object_key = str(mapping.get("object_key") or ontology.get("concept_key") or collection_name).strip()
    display_name = str(mapping.get("display_name") or ontology.get("display_name") or "").strip()
    return bool(object_key and display_name and collection_name and display_name != collection_name)


def _field_catalog_has_runtime_fields(field_catalog: list[Any]) -> bool:
