const auditBusinessObjectCreateDetail = (event: AuditEvent): AuditChangeDetail | null => {
    if (event.action !== 'execute-nocobase-business-object-create') return null;
    const result = objectAtPath(event.after, ['result']);
    const mapping = objectAtPath(event.after, ['mapping']);
    const displayName = primitiveText(result?.display_name)
        || primitiveText(mapping?.display_name)
        || metadataString(event.metadata, 'display_name')
        || metadataString(event.metadata, 'object_key')
        || '业务对象';
    const collectionName = primitiveText(result?.collection_name)
        || primitiveText(mapping?.collection_name)
        || metadataString(event.metadata, 'collection_name');
    const fields = Array.isArray(result?.fields) ? result.fields.filter(isPlainRecord) : [];
    const fieldCount = fields.length || metadataNumber(event.metadata, 'field_count') || 0;
    const fieldNames = fields
        .map((field) => primitiveText(field.title) || primitiveText(objectAtPath(field, ['uiSchema'])?.title) || primitiveText(field.name))
        .filter(Boolean);
    const initialCount = metadataNumber(event.metadata, 'initial_records_count') ?? Number(result?.initial_records_count || 0);
    return {
        title: '已创建业务对象',
        description: [
            `${displayName}${collectionName ? `（${collectionName}）` : ''}`,
            fieldCount ? `字段 ${fieldCount} 个` : '',
            initialCount ? `初始数据 ${initialCount} 条` : '',
            fieldNames.length ? `字段：${fieldNames.slice(0, 8).join('、')}${fieldNames.length > 8 ? ' 等' : ''}` : '',
        ].filter(Boolean).join(' · '),
        rows: [],
    };
};

const auditChangeDetail = (event: AuditEvent, rt: RuntimeText): AuditChangeDetail | null => {
    const ontologyDetail = ontologyCandidateChangeDetail(event);
    if (ontologyDetail) return ontologyDetail;
    const createDetail = auditBusinessObjectCreateDetail(event);
    if (createDetail) return createDetail;
    const connectorConfigDetail = connectorConfigChangeDetail(event);
    if (connectorConfigDetail) return connectorConfigDetail;
    const mappingDetail = objectMappingChangeDetail(event);
    if (mappingDetail) return mappingDetail;
    const backupDetail = backupChangeDetail(event);
    if (backupDetail) return backupDetail;

    const action = metadataString(event.metadata, 'action');
    if (event.action === 'execute-nocobase-record-batch-mutation') {
        const succeeded = metadataNumber(event.metadata, 'succeeded_count') ?? 0;
        const failed = metadataNumber(event.metadata, 'failed_count') ?? 0;
        const recordCount = metadataNumber(event.metadata, 'record_count') ?? succeeded + failed;
        const fields = metadataStringList(event.metadata, 'changed_fields').map(fieldDisplayLabel);
        return {
            title: '批量操作',
            description: [
                `${auditActionVerb(action)} ${auditObjectDisplay(event, rt)}`,
                `影响 ${recordCount} 条`,
                `成功 ${succeeded} 条`,
                `失败 ${failed} 条`,
                fields.length ? `字段 ${fields.join('、')}` : '',
            ].filter(Boolean).join(' · '),
            rows: auditBatchChangeRows(event),
        };
    }

    if (event.action === 'execute-nocobase-record-mutation') {
        const beforeRecord = auditBeforeRecord(event);
        const afterRecord = auditAfterRecord(event);
        const title = auditRecordTitle(afterRecord) || auditRecordTitle(beforeRecord);
        return {
            title: `${auditActionVerb(action)}业务数据`,
            description: title ? `记录：${title}` : auditObjectDisplay(event, rt),
            rows: auditSingleChangeRows(event),
        };
    }

    return genericPayloadChangeDetail(event);
};

const auditOperationSummary = (event: AuditEvent, rt: RuntimeText) => {
    const objectName = auditObjectDisplay(event, rt);
    const action = metadataString(event.metadata, 'action');
    const ontologyDetail = ontologyCandidateChangeDetail(event);
    if (ontologyDetail) {
        const counts = ontologyPublishImpactCounts(event);
        const impact = [
            counts.objectCount ? `对象 ${counts.objectCount}` : '',
            counts.fieldCount ? `字段 ${counts.fieldCount}` : '',
            counts.relationCount ? `关系 ${counts.relationCount}` : '',
        ].filter(Boolean).join('、');
        return `${ontologyDetail.title}：${ontologyCandidateTitle(event)}${impact ? `，影响${impact}` : ''}`;
    }
    const createDetail = auditBusinessObjectCreateDetail(event);
    if (createDetail) {
        const result = objectAtPath(event.after, ['result']);
        const mapping = objectAtPath(event.after, ['mapping']);
        const displayName = primitiveText(result?.display_name)
            || primitiveText(mapping?.display_name)
            || objectName;
        const collectionName = primitiveText(result?.collection_name)
            || primitiveText(mapping?.collection_name)
            || metadataString(event.metadata, 'collection_name');
        const fieldCount = metadataNumber(event.metadata, 'field_count')
            ?? (Array.isArray(result?.fields) ? result.fields.length : 0);
        return `创建业务对象：${displayName}${collectionName ? `（${collectionName}）` : ''}${fieldCount ? `，字段 ${fieldCount} 个` : ''}`;
    }
    if (event.action === 'execute-nocobase-record-batch-mutation') {
        const succeeded = metadataNumber(event.metadata, 'succeeded_count') ?? 0;
        const failed = metadataNumber(event.metadata, 'failed_count') ?? 0;
        const fields = metadataStringList(event.metadata, 'changed_fields').map(fieldDisplayLabel);
        return [
            `批量${auditActionVerb(action)} ${objectName}：成功 ${succeeded} 条`,
            `失败 ${failed} 条`,
            fields.length ? `字段 ${fields.join('、')}` : '',
        ].filter(Boolean).join('，');
    }
    if (event.action === 'execute-nocobase-record-mutation') {
        const rows = auditSingleChangeRows(event);
        const changed = rows.length
            ? rows.slice(0, 2).map((row) => `${row.field} ${row.before} → ${row.after}`).join('、')
            : '';
        return changed
            ? `${auditActionVerb(action)} ${objectName}：${changed}${rows.length > 2 ? ' 等' : ''}`
            : `${auditActionVerb(action)} ${objectName}`;
    }
    const detail = auditChangeDetail(event, rt);
    if (detail) {
        if (event.action === 'save-nocobase-connector-config') {
            const changed = detail.rows.slice(0, 2).map((row) => `${row.field} ${row.before} → ${row.after}`).join('、');
            return `保存 NocoBase 连接配置${changed ? `：${changed}${detail.rows.length > 2 ? ' 等' : ''}` : ''}`;
        }
        if (event.action === 'save-nocobase-object-mapping') {
            return `保存业务对象映射：${detail.rows[0]?.after || detail.description || objectName}`;
        }
        if (event.action === 'nocobase_sidecar_backup_record') {
            return `记录 NocoBase 备份：${detail.description || objectName}`;
        }
        const changed = detail.rows.slice(0, 2).map((row) => `${row.field} ${row.before} → ${row.after}`).join('、');
        if (changed) return `${detail.title}：${changed}${detail.rows.length > 2 ? ' 等' : ''}`;
    }
    return auditActionDisplayLabel(event.action, rt);
};

const shouldShowAuditActionSubtitle = (event: AuditEvent, rt: RuntimeText) => (
    auditOperationSummary(event, rt) !== auditActionDisplayLabel(event.action, rt)
);

const operationIdFromEvent = (event: AuditEvent | null) => (
    metadataString(event?.metadata, 'operation_id')
    || metadataString(event?.metadata, 'workbench_operation_id')
    || metadataString(event?.metadata, 'runtime_operation_id')
);

const auditObjectDisplay = (event: AuditEvent, rt: RuntimeText) => (
    (ontologyCandidateActions.has(String(event.action || '')) ? ontologyCandidateTitle(event) : '')
    || metadataString(event.metadata, 'display_name')
    || metadataString(event.metadata, 'object_key')
    || metadataString(event.metadata, 'collection_name')
    || auditResourceLabel(event.resource_type, rt)
);

const auditActorDisplay = (event: AuditEvent, rt: RuntimeText) => (
    metadataString(event.metadata, 'agent_name')
    || metadataString(event.metadata, 'user_name')
    || metadataString(event.metadata, 'operator_name')
    || metadataString(event.metadata, 'tool_name')
    || ({
        user: rt('user', '用户'),
        agent: rt('agent', '智能体'),
        system: rt('system', '系统'),
        tool: rt('tool', '工具'),
    }[String(event.actor_type || '')] ?? rt('operator', '执行方'))
);

const auditChannelDisplay = (event: AuditEvent, rt: RuntimeText) => {
    const channel = metadataString(event.metadata, 'channel') || metadataString(event.metadata, 'source_channel');
    const labels: Record<string, string> = {
        web: 'Web',
        feishu: rt('Feishu', '飞书'),
        lark: rt('Feishu', '飞书'),
        wechat: rt('WeChat', '微信'),
        wecom: rt('WeCom', '企微'),
