const auditImpactDisplay = (event: AuditEvent, rt: RuntimeText) => {
    if (ontologyCandidateActions.has(String(event.action || ''))) {
        const { objectCount, fieldCount, relationCount, skippedRelationCount, refreshTargets } = ontologyPublishImpactCounts(event);
        const parts = [
            objectCount ? `${objectCount} 个对象` : '',
            fieldCount ? `${fieldCount} 个字段` : '',
            relationCount ? `${relationCount} 条关系` : '',
            skippedRelationCount ? `${skippedRelationCount} 条待补全关系` : '',
            refreshTargets.length ? `刷新 ${refreshTargets.join('、')}` : '',
        ].filter(Boolean);
        return parts.join('，') || rt('semantic candidate', '语义候选');
    }
    const count = metadataNumber(event.metadata, 'succeeded_count')
        ?? metadataNumber(event.metadata, 'record_count')
        ?? metadataNumber(event.metadata, 'affected_count');
    if (count != null) return rt(`${count} records`, `${count} 条`);
    const recordIds = metadataStringList(event.metadata, 'record_ids');
    if (recordIds.length) return rt(`${recordIds.length} records`, `${recordIds.length} 条`);
    return rt('not recorded', '未记录');
};

const auditStatusDisplay = (event: AuditEvent, rt: RuntimeText) => {
    if (String(event.action || '').startsWith('publish-ontology')) return rt('published', '已发布');
    if (event.action === 'reject_ontology_candidate') {
        return rt('rejected', '已驳回');
    }
    const rollbackStatus = metadataString(event.metadata, 'rollback_status');
    if (rollbackStatus === 'rolled_back' || event.action === 'workbench_operation_rollback') return rt('rolled back', '已撤回');
    if (String(event.action || '').includes('failed')) return rt('failed', '失败');
    if (operationIdFromEvent(event)) return rt('reviewable', '可检查');
    return rt('recorded', '已记录');
};

const auditDetailRows = (event: AuditEvent | null, rt: RuntimeText) => {
    if (!event) return [];
    const fields = metadataStringList(event.metadata, 'changed_fields');
    const action = metadataString(event.metadata, 'action');
    return [
        [rt('Business object', '业务对象'), auditObjectDisplay(event, rt)],
        [rt('Operator', '执行方'), auditActorDisplay(event, rt)],
        [rt('Channel', '来源'), auditChannelDisplay(event, rt)],
        [rt('Impact', '影响范围'), auditImpactDisplay(event, rt)],
        [rt('Operation type', '操作类型'), action || auditActionDisplayLabel(event.action, rt)],
        [rt('Changed fields', '影响字段'), fields.join('、')],
        [rt('Audit continuity', '审计连续性'), auditIntegrityCheckText(event.current_hash, rt)],
    ].filter(([, value]) => value !== undefined && value !== null && value !== '');
};

