const terminalPreviewStatuses: AgentBusinessWorkspaceExternalPreviewStatus[] = ['completed', 'cancelled', 'failed'];

const isTerminalPreviewStatus = (status: string) => terminalPreviewStatuses.includes(status as AgentBusinessWorkspaceExternalPreviewStatus);

const readRollbackToken = (result: unknown): string | null => {
  if (!isPlainRecord(result)) return null;
  if (!readRollbackable(result)) return null;
  const directToken = stringValue(result.rollback_confirmation_token);
  if (directToken) return directToken;
  const body = isPlainRecord(result.result) ? result.result : null;
  const bodyToken = stringValue(body?.rollback_confirmation_token);
  if (bodyToken) return bodyToken;
  const operation = isPlainRecord(result.operation) ? result.operation : null;
  const operationResult = isPlainRecord(operation?.result) ? operation.result : null;
  return stringValue(operationResult?.rollback_confirmation_token) || null;
};

const readRollbackable = (result: unknown): boolean => {
  if (!isPlainRecord(result)) return false;
  if (result.rollbackable === true) return true;
  const body = isPlainRecord(result.result) ? result.result : null;
  if (body?.rollbackable === true) return true;
  const operation = isPlainRecord(result.operation) ? result.operation : null;
  return operation?.rollbackable === true;
};

const readRollbackOperationId = (result: unknown, fallbackOperationId: string): string | null => {
  if (!readRollbackable(result)) return null;
  if (!isPlainRecord(result)) return fallbackOperationId;
  const directId = stringValue(result.rollback_operation_id);

  if (directId) return directId;
  const body = isPlainRecord(result.result) ? result.result : null;
  const bodyId = stringValue(body?.rollback_operation_id);
  if (bodyId) return bodyId;
  const operation = isPlainRecord(result.operation) ? result.operation : null;
  return stringValue(operation?.rollback_operation_id) || stringValue(operation?.id) || fallbackOperationId;
};

const readRollbackReasonCode = (result: unknown): string | null => {
  if (!isPlainRecord(result)) return null;
  const operation = isPlainRecord(result.operation) ? result.operation : null;
  const body = isPlainRecord(result.result) ? result.result : null;
  return stringValue(result.not_rollbackable_reason_code)
    || stringValue(body?.not_rollbackable_reason_code)
    || stringValue(operation?.not_rollbackable_reason_code)
    || null;
};

const readRollbackManualHandlingGuidance = (result: unknown): string | null => {
  if (!isPlainRecord(result)) return null;
  const operation = isPlainRecord(result.operation) ? result.operation : null;
  const body = isPlainRecord(result.result) ? result.result : null;
  return stringValue(result.manual_handling_guidance)
    || stringValue(body?.manual_handling_guidance)
    || stringValue(operation?.manual_handling_guidance)
    || null;
};

const readRollbackPatch = (
  result: unknown,
  fallbackOperationId: string,
): Pick<AgentBusinessWorkspaceExternalPreviewPatch, 'rollbackToken' | 'rollbackable' | 'rollbackOperationId' | 'rollbackReasonCode' | 'rollbackManualHandlingGuidance'> => ({
  rollbackToken: readRollbackToken(result),
  rollbackable: readRollbackable(result),
  rollbackOperationId: readRollbackOperationId(result, fallbackOperationId),
  rollbackReasonCode: readRollbackReasonCode(result),
  rollbackManualHandlingGuidance: readRollbackManualHandlingGuidance(result),
});

