def connector_mappings_from_ontology_mappings(
    mappings: list[dict[str, Any]],
    *,
    concepts_by_id: dict[str, dict[str, Any]],
    live_source_field_refs: set[str] | None = None,
) -> list[dict[str, Any]]:
    connector_mappings = [
        _ontology_mapping_to_connector_mapping_payload(
            mapping,
            concepts_by_id=concepts_by_id,
            live_source_field_refs=live_source_field_refs,
        )
        for mapping in mappings
        if _ontology_mapping_supports_nocobase_collection_execution(mapping)
        and connector_mapping_runtime_eligible(mapping)
    ]
    return merge_connector_execution_mappings(connector_mappings)


def merge_connector_execution_mappings(
    *mapping_groups: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    merged: dict[str, dict[str, Any]] = {}
    order: list[str] = []
    for mappings in mapping_groups:
        for mapping in mappings:
            if not isinstance(mapping, dict):
                continue
            if not connector_execution_mapping_runtime_eligible(mapping):
                continue
            key = str(mapping.get("collection_name") or mapping.get("resource_ref") or "").strip()
            if not key:
                continue
            if key not in merged:
                merged[key] = deepcopy(mapping)
                order.append(key)
                continue
            merged[key] = merge_connector_mapping_payload(merged[key], mapping)
    return [merged[key] for key in order]


def published_connector_execution_mappings_can_skip_live_fallback(mappings: list[dict[str, Any]]) -> bool:
    """Return true when published mappings contain enough facts for runtime execution."""
    if not mappings:
        return False
    for mapping in mappings:
        if not isinstance(mapping, dict) or not connector_mapping_runtime_eligible(mapping):
            return False
        if str(mapping.get("collection_name") or "").strip() == "":
            return False
        metadata = mapping.get("metadata") if isinstance(mapping.get("metadata"), dict) else {}
        if metadata.get("mapping_source") != "published_ontology_mapping":
            return False
        if not _mapping_has_published_object_identity(mapping):
            return False
        field_catalog = metadata.get("field_catalog") if isinstance(metadata.get("field_catalog"), list) else []
        if not _field_catalog_has_runtime_fields(field_catalog):
            return False
    return True


def connector_execution_mapping_runtime_eligible(
    mapping: Any,
) -> bool:
    payload = _public_ontology_payload(mapping)
    if not connector_mapping_runtime_eligible(payload):
        return False
    metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
    mapping_source = str(payload.get("mapping_source") or metadata.get("mapping_source") or "").strip()
    return mapping_source in _EXECUTION_FACT_MAPPING_SOURCES


