    def __init__(
        self,
        *,
        session_factory: Any = async_session,
        get_config: Any = get_nocobase_connector_config,
        execute_create: Any = execute_nocobase_business_object_create,
    ) -> None:
        self._session_factory = session_factory
        self._get_config = get_config
        self._execute_create = execute_create

    async def execute(self, *, permit: GatePermit, request: dict[str, Any]) -> dict[str, Any]:
        provider_request = self._require_provider_request(request)
        expected_revision = self._require_revision(request, key="connector_config_revision")
        async with self._session_factory() as session:
            config = await self._get_config(session, permit.tenant_id, include_secret=True)
        current_revision = self._require_revision(config, key="config_revision")
        if not hmac.compare_digest(current_revision, expected_revision):
            raise PermissionError("NOCOBASE_CONNECTOR_CONFIG_REVISION_MISMATCH")

        expected_collection = str(request.get("collection_name") or "").strip()
        if not expected_collection or str(provider_request.get("collection_name") or "").strip() != expected_collection:
            raise ValueError("PROVIDER_REQUEST_INVALID")
        raw_result = await self._execute_create(config, provider_request)
        if not isinstance(raw_result, dict):
            raise ValueError("PROVIDER_RESULT_INVALID")
        collection_name = str(raw_result.get("collection_name") or "").strip()
        if collection_name != expected_collection:
            raise ValueError("PROVIDER_RESULT_INVALID")
        public_result = {
            "collection_name": collection_name,
            "display_name": str(raw_result.get("display_name") or provider_request.get("display_name") or "").strip(),
            "fields": deepcopy(raw_result.get("fields") if isinstance(raw_result.get("fields"), list) else []),
            "ui_page": deepcopy(raw_result.get("ui_page") if isinstance(raw_result.get("ui_page"), dict) else {}),
            "initial_records_count": int(raw_result.get("initial_records_count") or 0),
            "initial_records": deepcopy(
                raw_result.get("initial_records") if isinstance(raw_result.get("initial_records"), list) else []
            ),
        }
        return {
            "actual_scope": {
                "provider": "nocobase",
                "capability": "business_object.create",
                "connector_config_revision": current_revision,
                "object_key": str(provider_request.get("object_key") or "").strip(),
                "collection_name": collection_name,
                "result": public_result,
            }
        }

    @staticmethod
    def _require_provider_request(request: dict[str, Any]) -> dict[str, Any]:
        if (
            str(request.get("provider") or "").strip() != "nocobase"
            or str(request.get("capability") or "").strip() != "business_object.create"
        ):
            raise ValueError("PROVIDER_REQUEST_INVALID")
        provider_request = request.get("request")
        if not isinstance(provider_request, dict):
            raise ValueError("PROVIDER_REQUEST_INVALID")
        return deepcopy(provider_request)

    @staticmethod
    def _require_revision(value: dict[str, Any], *, key: str) -> str:
        revision = str(value.get(key) or "").strip()
        if not revision:
            raise ValueError("NOCOBASE_CONNECTOR_CONFIG_REVISION_REQUIRED")
        return revision

